      "default": "lf"
    },
    "match_type": {
      "description": "The matching engine used to interpret include and exclude patterns.",
      "enum": ["standard", "doublestar", "gitignore"],
      "default": "standard"
    },
    "output_format": {
      "description": "The format to use for command output.",
      "enum": ["default", "line", "gitlab"],
      "default": "default"
