      ]
    }
  },
  "$defs": {
    "basicFormatter": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "description": "The type of formatter to use.",
          "enum": ["basic"],
          "default": "basic"
        },
        "indent": {
          "description": "The indentation level in spaces to use for the formatted yaml.",
          "type": "integer",
          "default": 2
        },
        "include_document_start": {
          "description": "Include the document start marker (---) at the beginning of documents.",
          "type": "boolean",
          "default": false
        },
        "line_ending": {
          "description": "Line ending to use, overrides the global line_ending.",
          "enum": ["lf", "crlf"]
        },
        "retain_line_breaks": {
          "description": "Retain line breaks in formatted yaml.",
          "type": "boolean",
          "default": false
        },
        "retain_line_breaks_single": {
          "description": "Retain line breaks in formatted yaml, collapsing multiple consecutive line breaks into a single line break.",
          "type": "boolean",
          "default": false
        },
        "disallow_anchors": {
          "description": "If true, disallow anchors and aliases in the yaml, throwing an error if any are found.",
          "type": "boolean",
          "default": false
        },
        "max_line_length": {
          "description": "Set the maximum line length. Comments and folded scalars may be reflowed to fit.",
          "type": "integer"
        },
        "scan_folded_as_literal": {
          "description": "Parse folded block scalars (>) as literal block scalars (|), retaining line breaks.",
          "type": "boolean",
          "default": false
        },
        "indentless_arrays": {
          "description": "Render array elements at the same indentation level as their parent key.",
          "type": "boolean",
          "default": false
        },
        "drop_merge_tag": {
          "description": "Assume that any well formed merge using a merge tag (<<) is a merge and drop the tag.",
          "type": "boolean",
          "default": false
        },
        "pad_line_comments": {
          "description": "The number of padding spaces to insert before line comments.",
          "type": "integer",
          "default": 1
        },
        "trim_trailing_whitespace": {
          "description": "Trim trailing whitespace from lines.",
          "type": "boolean",
          "default": false
        },
        "eof_newline": {
          "description": "Always add a newline at the end of the file. Useful when retain_line_breaks is true and a file does not have a trailing newline.",
          "type": "boolean",
          "default": false
        },
        "strip_directives": {
          "description": "Strip directive lines (lines beginning with %) before formatting.",
          "type": "boolean",
          "default": false
        },
        "array_indent": {
          "description": "The indentation level in spaces to use for arrays, overrides the value of indent for arrays.",
          "type": "integer"
        },
        "indent_root_array": {
          "description": "Apply array indentation to the root level of the document.",
          "type": "boolean",
          "default": false
        },
        "disable_alias_key_correction": {
          "description": "Disable the correction of alias keys in the yaml.",
          "type": "boolean",
          "default": false
        },
        "force_array_style": {
          "description": "Force the style of arrays in the formatted yaml.",
          "enum": ["", "flow", "block"],
          "default": ""
        },
        "force_quote_style": {
          "description": "Force the style of quotes in the formatted yaml.",
          "enum": ["", "single", "double"],
          "default": ""
        }
      }
    },
    "kyamlFormatter": {
      "type": "object",
      "additionalProperties": false,
      "required": ["type"],
      "properties": {
        "type": {
          "description": "The type of formatter to use.",
          "const": "kyaml"
        }
      }
    }
  }
}
